package ingest

import("encoding/binary";"errors";"fmt")
func decodeSnappy(src []byte)([]byte,error){total,n:=binary.Uvarint(src);if n<=0{return nil,errors.New("missing uncompressed length")};src=src[n:];if total>512<<20{return nil,errors.New("payload too large")};dst:=make([]byte,0,int(total));for len(src)>0&&uint64(len(dst))<total{tag:=src[0];src=src[1:];switch tag&3{case 0:l:=int(tag>>2);if l<60{l++}else{extra:=l-59;if len(src)<extra{return nil,errors.New("short literal length")};x:=0;for i:=0;i<extra;i++{x|=int(src[i])<<(8*i)};src=src[extra:];l=x+1};if len(src)<l{return nil,errors.New("short literal")};dst=append(dst,src[:l]...);src=src[l:];case 1:if len(src)<1{return nil,errors.New("short copy1")};l:=4+int((tag>>2)&7);off:=int((tag&0xe0)<<3)|int(src[0]);src=src[1:];var err error;dst,err=copySnappy(dst,off,l);if err!=nil{return nil,err};case 2:if len(src)<2{return nil,errors.New("short copy2")};l:=1+int(tag>>2);off:=int(binary.LittleEndian.Uint16(src[:2]));src=src[2:];var err error;dst,err=copySnappy(dst,off,l);if err!=nil{return nil,err};case 3:if len(src)<4{return nil,errors.New("short copy4")};l:=1+int(tag>>2);off:=int(binary.LittleEndian.Uint32(src[:4]));src=src[4:];var err error;dst,err=copySnappy(dst,off,l);if err!=nil{return nil,err}}};if uint64(len(dst))!=total{return nil,fmt.Errorf("decoded length %d != %d",len(dst),total)};return dst,nil}
func copySnappy(dst []byte,off,l int)([]byte,error){if off<=0||off>len(dst){return nil,errors.New("invalid snappy offset")};for i:=0;i<l;i++{dst=append(dst,dst[len(dst)-off])};return dst,nil}
